from functools import reduce


def total(values):
    if isinstance(values, tuple):
        return reduce(lambda a, b: a + b, values, 0)
    return sum([v for v in values])

def fizzbuzz(n):
    out = []
    for i in range(1, n + 1):
        s = ('Fizz' if i % 3 == 0 else '') + ('Buzz' if i % 5 == 0 else '')
        out.append(s or str(i))
    return out

def is_prime(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def word_count(text):
    counts = {}
    for w in text.split():
        counts[w] = counts.get(w, 0) + 1
    return counts

def factorial(n):
    if n < 0:
        raise ValueError('n must be >= 0')
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def fibonacci(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def second_largest(nums):
    distinct = sorted(set(nums))
    if len(distinct) < 2:
        raise ValueError('need two distinct values')
    return distinct[-2]
